custom_css:
/*Header*/
.page-heading {
    margin-bottom: 75px;
}
.header-color-dark .menu-wrapper .menu > li.current-menu-item > a:after,
.header-color-dark .menu-wrapper .menu > li > a:hover:after,
.header-color-dark .menu-wrapper .menu > li > a:after{
    background-color: #651fff;
    margin-top: 8px;
}
.menu-wrapper .menu > li.current-menu-item > a:after,
.header-color-dark .menu-wrapper .menu > li > a:hover:after{
    left: 2.3em;
    right: 2.3em;
    opacity: 1;
}
.fixed-header {
    border-top:none;
}
.header-logo{
    width:25% !important;
}


/*Shop*/
.single_add_to_cart_button.button:hover {
    border-color:#212121;
    background:#212121;
}
.product-share li a:hover{
    color:#651fff !important;
}
.product-share li a{
    color:#b6b8b8 !important;
}
.single_add_to_cart_button.button{
     font-size: 14px;
    text-transform: capitalize;
    font-family: Poppins;
    font-weight: 400;
    background: #651fff;
    border-color: #651fff;
    width: 176px;
    min-width: 176px;
    height: 50px;
    margin-bottom: 10px;
    margin-right:0;
}
.single-product .compare.button{
    margin:0 auto !important;
}
.single-product .qty-span{
    margin-bottom:5px;
}
.single-product .product-information .qty-span,
.single-product  .add_to_wishlist,
.single-product .compare.button{
    font-size: 18px !important;
    font-family: Playfair Display;
    font-weight: 400;
    text-transform: capitalize;
    letter-spacing:0 !important;
}
.product-information .price{
    margin-bottom: 20px;
    font-size: 60px;
    color: #651fff;
    font-family: Playfair Display;
    font-weight: 700;
}
.woocommerce-main-image.pswp-main-image > img{
    height:471px !important;
}
.product-information .cart + .yith-wcwl-add-to-wishlist{
    margin-bottom: 0px;
}
.product-information .product_meta{
    margin-bottom: 5px;
    margin-top: 25px;
    border-bottom: 1px solid #f5f5f5;
}
.single-product-xsmall .menu-social-icons li a {
    padding: 3px 8px;
}
.single-product .product-share {
    width:160px;
    margin:0 auto;
    padding-top: 10px;
    overflow: hidden;
    border-top: none;
    border-bottom: none;
    text-transform: uppercase;
    padding-bottom:0 !important;
}
.product-content.sidebar-position-without .col-lg-9 {
    width: 60% !important;
}
.quantity.buttons_added.buttons_added input[type="number"] {
    margin-left: 0;
    margin-right: 0;
    background: #fff;
    border-top-color: #d9d9d9;
    border-bottom-color: #d9d9d9;
    font-size: 14px;
    color: #651fff;
    font-weight: 400;
    font-family: Poppins;
}
.single-product .quantity {
    display: table;
    margin: 0 auto 30px;
}
.quantity.buttons_added span {
    border: 1px solid #d1d1d1 !important;
    display: inline-block;
    height: 38px;
    line-height: 38px;
    border: none;
    background-color: #fff;
}
.product-content.sidebar-position-without .product-information{
    width:40%;
}
.single-product .product-information-inner *{
    text-align: center !important;
}
.single-product .product-information-inner {
    border: 2px solid #651fff;
    padding: 40px 60px 50px 60px;
    text-align: center !important;
}
.fixed-content h4.title,
.fixed-content .products-page-cats,
.single-product .product-share > span{
    display:none;
}
.single-product .swiper-slide.images.woocommerce-product-gallery{
    text-align:left;
}
.arhive .page-heading,
.single-product .page-heading{
    background-image:url(http://8theme.com/demo/xstore/2/designers/wp-content/uploads/sites/11/2018/04/shop-breacrambs.jpg);
    background-size:cover;
    background-position:center center;
}

/*content*/
.head-after:after{
    display:block;
    content:" ";
    width:86px;
    height:2px;
    background:#651fff;
    margin-left: -83px;
    margin-top: -14px;
}
.vc_btn3.vc_btn3-color-blue:hover{
    background-color: #212121 !important;
}
.vc_btn3.vc_btn3-color-blue,
.vc_btn3.vc_btn3-color-blue.vc_btn3-style-flat {
    font-family: Poppins;
    font-size: 14px;
    font-weight: 400;
    color: #fff;
    background-color: #651fff;
    border-radius: 0;
    height: 50px;
    width: 174px;
}
.initial{
    text-transform:initial !important;
}
.height-300{
    height:300px;
}
.lowercase{
    text-transform:lowercase !important;
}
.letter-1{
    letter-spacing:1px !important;
}
.contain{
    background-size:contain !important;
}
/*Blog*/
.single-post .content-article.entry-content > div:first-child .wpb_text_column{
    margin-bottom:25px !important;
}
.form-submit input[type="submit"]:hover {
    background-color: #212121;
    border-color: #212121;
}
.single-post .form-submit .submit{
    font-size: 14px;
    text-transform: initial;
    font-weight: 400;
    color: #fff;
    width: 205px;
    height: 52px;
    margin-bottom:3vw;
}
.etheme_portfolio-template-default .vc_separator.vc_sep_color_blue .vc_sep_line {
        border-color: #651fff !important;
}
 textarea.form-control::placeholder,
.comment-respond input[type=text]::placeholder,
.comment-respond input[type=email]::placeholder{
    color:#a3a3a3;
    font-size:16px;
}
 textarea.form-control:focus,
.comment-respond input[type=text]:focus,
.comment-respond input[type=email]:focus{
    border-bottom:2px solid #651fff !important;
}
.comment-respond input[type=text],
.comment-respond input[type=email]{
    height:44px;
}
textarea.form-control,
.comment-respond input[type=text],
.comment-respond input[type=email]{
    background: #fff !important;
    border-top-color: #fff !important;
    border-right-color: #fff !important;
    border-left-color: #fff !important;
    border-bottom-color: #f4f4f4 !important;
}
.comments-list .media-heading {
    font-weight: 400;
    font-size: 22px;
    margin-bottom: 0.4em;
    text-transform: inherit;
    color: #3e3e3e;
}
.author-info .media-heading {
    font-size: 26px;
    font-weight: 400;
    color:#3e3e3e;
}
.single-post .share-post {
    padding: 30px 0 25px;
}
.single-post .post-heading h2{
    display:none;
}
.post-categories{
    display:none;
}
.blog  .articles-pagination a:hover{
    background:#fff;
    color:#212121;
    border-color:#651fff;
}
.blog  .articles-pagination a{
    line-height: 28px;
    border: 2px solid #fff;
    font-family: "Playfair Display";
}
.blog .articles-pagination .current{
    background:#fff;
    line-height: 28px;
    color:#212121;
    border: 2px solid #651fff;
    font-family: "Playfair Display";
}
.content-grid2:hover .meta-post-timeline .time-day,
.content-grid2:hover .meta-post-timeline .time-mon {
    color: #fff !important;
}
.blog .content-grid2 .meta-post-timeline .time-mon {
    color: #212121;
    font-family: "Playfair Display";
    font-size: 14px;
}
.blog .time-day{
    font-size: 28px !important;
    color: #212121 !important;
    font-family: "Playfair Display";
    margin-top: 2px !important;
}
.blog .post-heading h2{
    margin-bottom:12px;
}
.blog .post-heading {
    margin-bottom: 7px;
}
.blog .post-heading h2 a{
    font-weight: 400;
    font-style: normal;
    color: #3e3e3e;
    font-size: 20px;
    text-transform: initial;
    letter-spacing: 0;
}
.meta-post .views-count:before,
 .meta-post .post-comments-count:before{
    color: #651fff;
}
.single-post .share-post .share-title,
.comments .title-alt span,
.comment-reply-title span{
    font-weight: 400;
    font-size: 20px;
    color: #212121;
}
.single-post .menu-social-icons li a:hover {
    color: #651fff !important;
    border: 1px solid #651fff !important;
}
.single-post .share-post .menu-social-icons li a {
    display: inline-block;
    padding: 7px 6px;
    border: 1px solid #fff;
    width: 30px;
    height: 30px;
    margin-left: 8px;
    color:#a3a3a3;
}
.single-post .meta-post,
.single-post .meta-post *{
    font-size:18px !important;
}
.single-post .post-heading {
    margin-bottom: 20px;
    margin-top: 30px;
}
.blog .post-comments-count span:last-child{
    display:none;
}
 .meta-post *,
 .meta-post{
    font-size: 15px;
    font-weight: 400;
    color: #c2c2c2 !important;
}
.blog .content-article p {
    font-size: 14px;
    line-height: 25px;
    font-weight: 400;
}
.blog .content-grid2 .meta-post-timeline {
    left: 6%;
    top: 41%;
    width: 61px;
    height: 64px;
}
.blog .grid-post-body{
    padding-left:20px;
    padding-top:35px;
}
.blog .wp-picture.blog-hover-zoom,
.blog .grid-post-body{
    width:50%;
    float:left;
    text-align:left !important;
}
.blog .page-heading,
.single-post .page-heading{
    background-image:url(http://8theme.com/demo/xstore/2/designers/wp-content/uploads/sites/11/2018/04/blog-breacrambs.jpg);
    background-size:cover;
    background-position:center center;
}
.responsive-padding-bg-2 .mpc-button.mpc-transition.letter-1,
.price__section .mpc-button.mpc-transition.letter-1{
    overflow:visible;
}
.responsive-padding-bg-2 .mpc-button.mpc-transition.letter-1:hover::after,
.responsive-padding-bg-2 .mpc-button.mpc-transition.letter-1:hover::before,
.tp-caption.rev-btn:hover::after,
.vc_general.vc_btn3:hover::after,
.price__section .mpc-button.mpc-transition.letter-1:hover::after,
.tp-caption.rev-btn:hover::before,
.vc_general.vc_btn3:hover::before,
.price__section .mpc-button.mpc-transition.letter-1:hover::before{
    background:#212121;
}
.responsive-padding-bg-2 .mpc-button.mpc-transition.letter-1::after,
.tp-caption.rev-btn::after,
.vc_general.vc_btn3::after,
.price__section .mpc-button.mpc-transition.letter-1::after{
    display:block;
    content:" ";
    width:30px;
    height:2px;
    background:#651fff;
    position: absolute;
    top: 49%;
    left: -28px;
}
.responsive-padding-bg-2 .mpc-button.mpc-transition.letter-1::before,
.tp-caption.rev-btn::before,
.vc_general.vc_btn3::before,
.price__section .mpc-button.mpc-transition.letter-1::before{
    display:block;
    content:" ";
    width:30px;
    height:2px;
    background:#651fff;
    position: absolute;
    top: 49%;
    right: -28px;
}
.fixed-header{
    box-shadow: 1px 1px 1px #efefef;
}
/*footer*/

.home footer.footer .copyright{
    margin-bottom:35px !important;
}
footer.footer .et-follow-buttons.buttons-size-normal a {
    padding: 0 8px;
}
.menu-element.horizontal .menu > li > a {
    padding: 0.77em 2em !important;
}
footer #menu-main-menu-2 li.current_page_item a::after,
footer #menu-main-menu-2 li a:hover::after {
    width: 50%;
    margin-top: 6px;
    opacity: .8;
}
footer #menu-main-menu-2 li a::after {
    background-color: #fff;
    margin-top: 6px;
    display: block;
    content: " ";
    height: 2px;
    width: 0;
    left: 50%;
    position: absolute;
    -webkit-transition: width .3s ease-in-out;
    -moz--transition: width .3s ease-in-out;
    transition: width .3s ease-in-out;
    -webkit-transform: translateX(-50%);
    -moz-transform: translateX(-50%);
    transform: translateX(-50%);
}
footer.footer ul.menu li a{
    font-family: Poppins;
    text-transform: initial !important;
    line-height: 16px;
    letter-spacing: 0.7px;
    font-weight: 400;
    font-style: normal;
    color: #fff !important;
    font-size: 16px !important;
}
.footer-bottom{
    display:none;
}

footer.footer .vc_single_image-wrapper:hover{
    opacity:.6;
    transition:0.4s;
}
footer.footer .vc_single_image-wrapper{
    transition:0.4s;
}
.img-hover{
    transition: 0.5s !important;
}

@media only screen and (min-width: 1900px) {
    .logo-block .mpc-grid-images > .mpc-item{
       padding:0 45px;
    }
    body .responsive-padding-bg > .vc_column-inner{
        padding-right: 225px !important;
        padding-left: 225px !important;
    }
    body .responsive-padding-bg-2 > .vc_column-inner{
        padding-right: 270px !important;
        padding-left: 270px !important;
    }
}
@media only screen and (max-width : 1024px)  {
    body .responsive-padding-bg-2 > .vc_column-inner{
        padding-right: 15px !important;
        padding-left: 15px !important;
    }
    body .responsive-padding-bg > .vc_column-inner{
        padding-right: 60px !important;
        padding-left: 60px !important;
    }
    body div.cover.section-about-us{
        overflow: visible !important;
     }
     body .section-about-us{
         background-image:none !important;
     }
     .menu-element.horizontal .menu>li>a {
         padding: 0.5em .3em !important;
     }
     .price__section .price-text{
        font-size:16px !important;
     }
     .responsive-padding-bg-2 .text-center .wpb_wrapper > h2:first-child{
        font-size:18px !important;
    }
    footer.footer .lowercase.letter-1{
        font-size:50px !important;
    }
    .initial.know{
        font-size:56px !important;
    }
    .size-40{
        font-size:40px !important;
    }
    .size-60{
        font-size:54px !important;
    }
    .head-after{
        padding-left:90px !important;
    }
    .responsive-padding-abouts > .vc_column-inner{
        padding-left: 20px !important;
    }
    .single-product .product-information-inner {
        padding: 20px 0px 40px 0px;
    }
    .single-product .product-share {
        width: 180px;
    }
}

@media only screen and (min-device-width : 1024px) and (max-device-width : 1600px)  {
    .size-60{
        font-size:60px !important;
    }
    footer.footer .menu-element.horizontal .menu>li>a {
        padding: .77em .6em !important;
    }
    .responsive-padding-bg-2 .text-center .wpb_wrapper > h2:first-child{
        font-size:18px !important;
    }
    body .responsive-padding-bg-2 > .vc_column-inner,
    body .responsive-padding-bg > .vc_column-inner{
        padding-right: 100px !important;
        padding-left: 100px !important;
    }
    .price__section .price-text{
        font-size:20px !important;
    }
    .initial.know{
        font-size:56px !important;
    }
}

@media only screen and (max-width: 480px){
    body footer.footer  .resp-left .wpb_single_image{
        text-align:left !important;
    }
    body footer.footer  .resp-right .wpb_single_image{
        text-align:right  !important;
    }
    .resp-width > .vc_column-inner {
        padding:0 !important;
    }
    .fixed-header .header-logo img{
        max-width: 40px !important;
    } 
    body .banner-block{
        padding-bottom:50px !important;
    }
    .et-follow-buttons.align-right {
        text-align: center !important;
    }
    body .responsive-margin-bottom{
        margin-bottom:35px !important;
    }
    .etheme_portfolio-template-default .vc_box_border_grey{
        margin-bottom:40px;
        margin-top:30px;
    }
    
    .product-content.sidebar-position-without .col-lg-9,
    .product-content.sidebar-position-without .product-information{
        width: 100% !important;
    }
    .blog .grid-post-body {
        padding-left: 0px;
    }
    article.blog-post .wp-picture {
        margin-bottom: 0px;
    }
    .blog .wp-picture.blog-hover-zoom, .blog .grid-post-body {
        width: 100%;
        float: none;
        text-align: center !important;
    }
    .blog .content-grid2 .meta-post-timeline {
        left: 50%;
        top: 0;
        width: 61px;
        height: 64px;
    }
    .articles-pagination {
        padding: 30px 0 25px 0;
    }
    .et_coutn-posts {
        float: left;
        margin-top: 18px;
        width: 50%;
    }
    footer.footer .contain{
        z-index: 0 !important;
        padding-bottom: 25px !important;
    }
    body .page-heading{
        padding-top: 60px !important;
        padding-bottom: 60px !important;
    }
    .price__section > .text-center{
        margin-bottom:80px;
    }
    .price__section > .text-center:last-child{
        margin-bottom:30px;
    }
    .fixed-header .container {
        padding-top: 0.4em;
        padding-bottom: 0.4em;
    }
    .header-wrapper header .container-wrapper {
        padding: 7px 0 0 0;
    }
    body .grid__img{
        margin-bottom: 100px !important;
    }
    body .home-price-block{
        margin-bottom:0 !important;
        padding-bottom: 100px !important;
    }
    
    body .section-about-us {
        margin-bottom:10px !important;
    }
    .responsive-padding-abouts .mpc-button{
        margin-bottom: 0 !important;
        margin-left: 0 !important;
        margin-top:30px;
    }
    .responsive-padding-abouts>.vc_column-inner {
        padding-top: 0 !important;
        padding-left: 15px !important;
        border: none !important;
    }
    .menu-element.horizontal .menu>li>a {
        padding: .6em .3em !important;
        font-size:13px !important;
    }
    footer.footer .wpb_single_image,
    footer.footer .menu{
        margin-bottom:25px !important;
        text-align:center !important;
    }
    .resp-width{
        width:30%;
        float:left;
        margin-left: 10px;
    }
    .follow{
        padding:30px 0;
    }
    .tparrows {
        top: 115% !important;
        left: 115% !important;
    }
    .mpc-map-wrap {
        position: relative;
        right: 0 !important;
        width: 100% !important;
        height:250px !important;
    }
    body .contacts-block .about-us  .vc_column-inner{
        padding-left:15px !important;
        margin-top: 0 !important;
        margin-bottom: 35px;
    }
    body .contacts-block .about-us  > .vc_column-inner{
        padding-bottom:30px !important;
    }
    .size-60{
        display:none;
    }
    .head-after{
        display:inline-block;
        font-size:24px !important;
    }
    body .responsive-padding-bg > .vc_column-inner{
        padding-right: 15px !important;
        padding-left: 15px !important;
    }
      body  .responsive-padding-bg  .services-block  .vc_column-inner{
        margin-left:0px !important;
        margin-right:0px !important;
        width: 90% !important;
        margin: 0 auto !important;
        margin-bottom:30px !important;
    }
    .responsive-padding-bg-2 .text-center{
        margin-bottom:40px !important;
    }
    footer #menu-main-menu-2 li.current_page_item a::after, footer #menu-main-menu-2 li a:hover::after {
        width: 0%; 
        margin-top: 0px; 
        opacity: 0; 
    }
    .mobile-menu-wrapper .menu > li {
        border-bottom: none; 
    }
    .wpb_revslider_element{
        margin-bottom: 10px;
    }
    
}

@media only screen and (min-width: 1600px){
    footer.footer > .container{
        width:1600px !important;
    }
}
